/**
 * Champion dataset access.
 *
 * The JSON is generated by `node tools/scrape.mjs` from
 * https://wiki.leagueoflegends.com/en-us/List_of_champions and the individual
 * champion pages. It is bundled at build time: the site has no runtime API,
 * no key and no origin requests.
 */
import data from './data/champions.json'

/** @typedef {import('./types.js').Champion} Champion */

export const meta = {
  generatedAt: data.generatedAt,
  source: data.source,
  license: data.license,
  count: data.champions.length,
}

/** @type {Champion[]} */
export const champions = data.champions

const bySlug = new Map()
const byLower = new Map()
for (const champion of champions) {
  bySlug.set(champion.slug, champion)
  byLower.set(champion.slug.toLowerCase(), champion)
}

/**
 * Look a champion up from a URL segment, case- and separator-insensitively.
 * `/ashe`, `/Ashe` and `/ashe` all resolve to the same champion.
 *
 * @param {string | undefined | null} value
 * @returns {Champion | undefined}
 */
export function findChampion(value) {
  if (!value) return undefined
  const raw = decodeURIComponent(String(value)).trim()
  if (!raw) return undefined
  return bySlug.get(raw) ?? byLower.get(raw.toLowerCase()) ?? byLower.get(raw.replace(/\s+/g, '_').toLowerCase())
}

/** Canonical, shareable path for a champion. */
export function championPath(champion) {
  return `/${champion.slug}`
}

/**
 * Fuzzy-ish search over name and epithet: prefix matches rank above substring
 * matches, and initials match ("tf" -> Twisted Fate).
 *
 * @param {string} query
 * @param {number} limit
 */
export function searchChampions(query, limit = 60) {
  const q = query.trim().toLowerCase()
  if (!q) return champions.slice(0, limit)
  const scored = []
  for (const champion of champions) {
    const name = champion.name.toLowerCase()
    const title = (champion.title || '').toLowerCase()
    let score = -1
    if (name === q) score = 0
    else if (name.startsWith(q)) score = 1
    else if (initials(name) === q) score = 2
    else if (name.includes(q)) score = 3
    else if (title.includes(q)) score = 4
    if (score >= 0) scored.push({ champion, score, name })
  }
  scored.sort((a, b) => a.score - b.score || a.name.localeCompare(b.name))
  return scored.slice(0, limit).map((s) => s.champion)
}

function initials(name) {
  return name
    .replace(/[^a-z\s']/g, '')
    .split(/[\s']+/)
    .filter(Boolean)
    .map((word) => word[0])
    .join('')
}
